import xarray as xr
from unittest.mock import patch, MagicMock
from satpy.readers.viirs_edr import VIIRSJRRFileHandler

def test_platform_name():
    filename_info = {"platform_shortname": "n21"}

    with patch('xarray.open_dataset') as mock_open:
        # Mock the returned dataset to avoid errors in __init__
        mock_ds = MagicMock()
        mock_open.return_value = mock_ds

        handler = VIIRSJRRFileHandler(
            filename="dummy.nc",
            filename_info=filename_info,
            filetype_info={}
        )

        try:
            name = handler.platform_name
            print(f"Platform name for n21: {name}")
            assert name == "NOAA-21"
        except KeyError as e:
            print(f"Caught KeyError: {e}")
            raise e

if __name__ == "__main__":
    test_platform_name()

